"""Walks generated by NVIDIA's own Kimodo pipeline (github.com/nv-tlabs/kimodo), for comparing with ours.

Uses the official package's loader, generation call and G1 MuJoCo export on the same
``Kimodo-G1-RP-v1`` weights, with the official defaults: the whole clip at once from text only,
separated guidance at the checkpoint's defaults, 100 DDIM steps, the generation script's
multi-prompt path with 5 transition frames, and no post-processing (the official script turns it
off for G1). The one substitution: the text encoder is a stand-in returning phrase embeddings
already computed with the same LLM2Vec encoder (its Llama base needs gated access), passed through
the loader's ``text_encoder`` argument.

Each clip is written as a segment file (``demo_walks``) for gait numbers and SONIC replay; the
window skips the first second (the start from rest).

    python official_kimodo.py --kimodo-src <nv-tlabs/kimodo checkout> --checkpoint-dir <dir holding Kimodo-G1-RP-v1> \\
        --text-cache <phrase embeddings> --out <segments dir> [--seconds 8] [--seeds 1000 ...]
"""
import argparse
import json
import os
import sys
import time
from pathlib import Path

import numpy as np
import torch

sys.path.insert(0, str(Path(__file__).resolve().parents[2]/'scripts'))  # agentic/scripts: paths.py
import paths  # noqa: F401  (puts this checkout's package first)
from kimodo_vla.oracle import demo_walks as dw

PROMPTS = {'forward': ('walk_forward', 'A person walks forward.'),
           'backward': ('walk_backward', 'A person walks backward.'),
           'left': ('sidestep_left', 'A person side steps to the left.'),
           'right': ('sidestep_right', 'A person side steps to the right.'),
           'turn': ('turn_left_in_place', 'A person turns to the left in place.')}


class CachedText:
    """Stands in for the official LLM2Vec encoder: returns a precomputed embedding for each prompt."""
    def __init__(self, cache_dir):
        self.table = {}
        for path in Path(cache_dir).glob('*.pt'):
            payload = torch.load(path, map_location='cpu', weights_only=True)
            self.table[payload['instruction'].strip()] = torch.as_tensor(payload['embedding']).float()

    def to(self, *args, **kwargs):
        return self

    def eval(self):
        return self

    def __call__(self, texts):
        single = isinstance(texts, str)
        texts = [texts] if single else texts
        missing = [t for t in texts if t.strip() and t.strip() not in self.table]
        if missing:
            raise KeyError(f'No cached embedding for {missing}')
        # [B, 1, 4096] and one token each, as the official LLM2Vec wrapper returns
        feat = torch.cat([self.table[t.strip()] if t.strip() else torch.zeros(1, 4096) for t in texts])[:, None]
        lengths = [1]*len(texts)
        return (feat[0], lengths[0]) if single else (feat, lengths)


def qpos_to_actions(qpos, fps):
    """Official MuJoCo qpos rows (root xyz, quaternion wxyz, 29 joints in the XML's order) -> actions at 50 Hz."""
    q = np.asarray(qpos, dtype=float)
    rows = np.concatenate([q[:, :3], q[:, [4, 5, 6, 3]], q[:, 7:]], axis=1)  # quaternion to xyzw, as LAFAN1 rows
    return dw.lafan1_actions(rows, fps=fps)


def main():
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument('--kimodo-src', required=True)
    p.add_argument('--checkpoint-dir', required=True)
    p.add_argument('--text-cache', required=True)
    p.add_argument('--out', required=True)
    p.add_argument('--seconds', type=float, default=8.)
    p.add_argument('--seeds', type=int, nargs='+', default=[1000, 1001, 1002, 1003, 1004])
    p.add_argument('--steps', type=int, default=100, help='DDIM steps (the official script\'s default is 100)')
    p.add_argument('--directions', nargs='+', default=list(PROMPTS))
    args = p.parse_args()
    sys.path.insert(0, str(Path(args.kimodo_src).resolve()))
    os.environ['CHECKPOINT_DIR'] = str(Path(args.checkpoint_dir).resolve())
    os.environ['LOCAL_CACHE'] = 'True'
    from kimodo import load_model
    from kimodo.exports.mujoco import MujocoQposConverter
    from kimodo.tools import seed_everything
    model, name = load_model('Kimodo-G1-RP-v1', device='cuda', text_encoder=CachedText(args.text_cache),
                             return_resolved_name=True)
    converter = MujocoQposConverter(model.skeleton)
    names = [j.get('name') for j in __import__('xml.etree.ElementTree', fromlist=['x']).parse(converter.xml_path).iter('joint')
             if j.get('name') and j.get('type', 'hinge') == 'hinge']
    if tuple(names) != dw.LAFAN1_G1_JOINTS:
        raise SystemExit(f'Unexpected joint order in {converter.xml_path}: {names}')
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=False)
    frames = int(args.seconds*model.fps)
    fk = dw.g1_fk()
    rows = []
    for direction in args.directions:
        key, prompt = PROMPTS[direction]
        for seed in args.seeds:
            seed_everything(seed)
            began = time.time()
            motion = model([prompt], [frames], num_denoising_steps=args.steps, num_samples=1, multi_prompt=True,
                           num_transition_frames=5, post_processing=False, return_numpy=True)  # as generate.py calls it
            qpos = converter.dict_to_qpos(motion, root_quat_w_first=True)
            qpos = np.asarray(qpos)[0] if np.asarray(qpos).ndim == 3 else np.asarray(qpos)
            actions = qpos_to_actions(qpos, model.fps)
            window = [int(dw.RATE), len(actions)-1]
            seg = {'name': f'official-{direction}-s{seed}', 'direction': direction, 'window': window,
                   'source': {'pipeline': 'nv-tlabs/kimodo', 'model': name, 'prompt': prompt, 'seed': seed,
                              'seconds': args.seconds, 'diffusion_steps': args.steps, 'post_processing': False},
                   'actions': actions.tolist()}
            (out/f"{seg['name']}.json").write_text(json.dumps(seg))
            a = actions[window[0]:]
            summary = dw.window_summary(actions, *window)
            g = dw.stepping(dw.reference_feet(a, fk))
            rows.append({'name': seg['name'], 'direction': direction, 'seed': seed, 'window': summary, 'gait': g,
                         'seconds_to_generate': time.time()-began})
            print(seg['name'], f"{summary['speed_m_s']:.2f} m/s, disp {np.round(summary['displacement_m'], 2).tolist()}, "
                  f"yaw {summary['yaw_deg']:.0f}, slide {g['slide_m_s'] or 0:.3f}, both {g['both_moving']:.2f}, "
                  f"step {g['step_length_m'] or 0:.2f}", flush=True)
    (out/'segments.json').write_text(json.dumps({'segments': rows}, indent=1))


if __name__ == '__main__':
    main()
